请对以下 case 进行三维加权评分。

=== case_id ===
Case-27-utility-bill-007

=== 用户原始指令 (query.txt) ===
搞个电费卡,余额数字会变,能直接进入缴费,欠费就红色提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个电费卡,余额数字会变,能直接进入缴费,欠费就红色提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "utility://electricity/pay"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "utilityBill": {
        "accountName": {
          "type": "string",
          "description": "电费账户名称或账单对象名称。",
          "sampleValue": "电费余额"
        },
        "balanceText": {
          "type": "string",
          "description": "当前电费余额数字展示文本，会随运行时数据变化。",
          "sampleValue": "28.60"
        },
        "dueText": {
          "type": "string",
          "description": "缴费截止时间或账期提示。",
          "sampleValue": "7月12日前缴费"
        },
        "statusText": {
          "type": "string",
          "description": "欠费或正常缴费状态提示文案。",
          "sampleValue": "欠费提醒"
        },
        "statusColor": {
          "type": "string",
          "description": "状态提示文字颜色；欠费时使用告警红色。",
          "sampleValue": "#ffdb6b42"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_charge.png",
      "description": "充电/闪电 PNG 图标，适合表示电费、用电与缴费入口的视觉识别。"
    }
  ]
}

